+.product-row{display:flex;align-items:center;justify-content:space-between;gap:10px}
+.price{
+  font-weight:950;
+  color: rgba(27,67,50,0.95);
+  background: rgba(45,106,79,0.10);
+  padding: 8px 10px;border-radius:999px;
+}
+.mini{
+  font-size:12px;color:rgba(31,42,36,0.74);
+  display:inline-flex;align-items:center;gap:8px;
+}
+.spark{width:10px;height:10px;border-radius:50%;background: var(--accent-2)}
+
+/* Highlights banner */
+.highlights{
+  padding: 14px 0 12px;
+}
+.highlights-banner{
+  border-radius: var(--radius-lg);
+  background: linear-gradient(135deg, rgba(45,106,79,0.98), rgba(27,67,50,0.98));
+  color: rgba(255,255,255,0.96);
+  box-shadow: 0 20px 44px rgba(27,67,50,0.22);
+  position:relative;
+  overflow:hidden;
+}
+.highlights-banner::before{
+  content:"";
+  position:absolute;inset:-2px;
+  background:
+    radial-gradient(540px 260px at 18% 25%, rgba(244,162,97,0.35), transparent 60%),
+    radial-gradient(520px 260px at 80% 55%, rgba(233,196,106,0.25), transparent 62%);
+  opacity:0.9;
+}
+.highlights-grid{
+  position:relative;
+  z-index:1;
+  display:grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 14px;
+  padding: 18px;
+}
+.stat{
+  background: rgba(255,255,255,0.10);
+  border: 1px solid rgba(255,255,255,0.18);
+  border-radius: 18px;
+  padding: 14px 14px 12px;
+}
+.stat-num{font-family:"Nunito", ui-sans-serif, system-ui;font-size:26px;font-weight:950;letter-spacing:-0.02em;margin:0}
+.stat-label{margin:4px 0 0;font-weight:800}
+.stat-sub{margin:4px 0 0;color:rgba(255,255,255,0.82);font-size:13px}
+
+/* Seasonal picks */
+.two-col{display:grid;grid-template-columns: 1fr 1fr;gap:16px}
+.callout{
+  border-radius: var(--radius-lg);
+  background: rgba(255,255,255,0.64);
+  border:1px solid rgba(45,106,79,0.12);
+  box-shadow: var(--shadow);
+  padding: 18px;
+  position:relative;
+  overflow:hidden;
+}
+.callout::before{
+  content:"";
+  position:absolute;inset:-2px;
+  background: radial-gradient(520px 240px at 20% 0%, rgba(233,196,106,0.24), transparent 60%);
+  opacity:0.9;
+}
+.callout > *{position:relative;z-index:1}
+.picks{display:grid;grid-template-columns: 1fr 1fr;gap:12px}
+.pick{
+  border-radius: 18px;
+  background: rgba(255,255,255,0.88);
+  border: 1px solid rgba(45,106,79,0.12);
+  padding: 14px;
+  box-shadow: 0 10px 22px rgba(20,30,25,0.08);
+}
+.pick-title{margin:0;font-weight:950;letter-spacing:-0.02em}
+.pick-desc{margin:6px 0 10px;color:var(--muted);font-size:13px}
+.pick-price{font-weight:950;color: rgba(27,67,50,0.95)}
+
+/* Categories */
+.category-grid{display:grid;grid-template-columns: repeat(5, 1fr);gap:12px}
+.category-card{
+  position:relative;
+  border-radius: var(--radius-lg);
+  overflow:hidden;
+  border:1px solid rgba(45,106,79,0.12);
+  box-shadow: 0 12px 24px rgba(20,30,25,0.10);
+  min-height: 160px;
+  cursor:pointer;
+  transform: translateZ(0);
+  transition: transform 180ms ease, box-shadow 180ms ease;
+}
+.category-card:hover{transform: scale(1.03);box-shadow: 0 18px 34px rgba(20,30,25,0.14)}
+.category-card img{width:100%;height:100%;object-fit:cover;filter:saturate(1.03) contrast(1.02)}
+.category-overlay{
+  position:absolute;inset:0;
+  background: linear-gradient(180deg, rgba(0,0,0,0.0), rgba(0,0,0,0.58));
+  opacity:0;
+  display:flex;align-items:flex-end;
+  padding: 14px;
+  transition: opacity 180ms ease;
+}
+.category-card:hover .category-overlay{opacity:1}
+.category-name{
+  font-family:"Nunito", ui-sans-serif, system-ui;
+  font-weight:950;
+  letter-spacing:-0.02em;
+  color: rgba(255,255,255,0.98);
+  font-size: 16px;
+}
+.category-chip{
+  position:absolute;left:12px;top:12px;
+  background: rgba(254,250,224,0.92);
+  border: 1px solid rgba(45,106,79,0.16);
+  padding: 6px 10px;border-radius:999px;
+  font-weight:900;font-size:12px;color:rgba(45,106,79,0.92);
+}
+
+/* Store locator */
+.locator{
+  border-radius: var(--radius-lg);
+  background: rgba(255,255,255,0.66);
+  border: 1px solid rgba(45,106,79,0.12);
+  box-shadow: var(--shadow);
+  padding: 18px;
+}
+.form-row{display:flex;gap:10px;flex-wrap:wrap}
+.field{
+  flex: 1 1 240px;
+  display:flex;align-items:center;gap:10px;
+  padding: 12px 14px;
+  border-radius: 999px;
+  background: rgba(255,255,255,0.92);
+  border:1px solid rgba(45,106,79,0.14);
+  box-shadow: 0 10px 20px rgba(20,30,25,0.06);
+}
+.field input{
+  border:0;outline:none;background:transparent;
+  width:100%;font-size:15px;
+}
+.field:focus-within{box-shadow: 0 0 0 5px var(--ring), 0 10px 20px rgba(20,30,25,0.08)}
+
+.results{margin-top:14px;display:grid;gap:10px}
+.store{
+  border-radius: 18px;
+  background: rgba(255,255,255,0.92);
+  border:1px solid rgba(45,106,79,0.12);
+  padding: 14px;
+  display:grid;grid-template-columns: 1.2fr 1.2fr 0.8fr 0.5fr;
+  gap: 10px;
+  align-items:start;
+}
+.store h4{margin:0;font-weight:950;letter-spacing:-0.02em}
+.store p{margin:6px 0 0;color:var(--muted);font-size:13px}
+.pill{
+  display:inline-flex;align-items:center;gap:8px;
+  background: rgba(45,106,79,0.10);
+  border:1px solid rgba(45,106,79,0.14);
+  padding: 7px 10px;border-radius:999px;
+  font-weight:850;
+  width: fit-content;
+}
+.pill .spark{background: var(--accent)}
+.hint{margin-top:10px;color:rgba(31,42,36,0.68);font-size:13px}
+.error{color:#9b2226;font-weight:800}
+
+/* Newsletter */
+.newsletter{
+  border-radius: var(--radius-lg);
+  background: linear-gradient(135deg, rgba(244,162,97,0.26), rgba(233,196,106,0.22));
+  border:1px solid rgba(45,106,79,0.12);
+  box-shadow: var(--shadow);
+  padding: 18px;
+  display:grid;grid-template-columns: 1.2fr 0.8fr;gap: 14px;align-items:center;
+}
+.note{
+  border-radius: 18px;
+  background: rgba(255,255,255,0.74);
+  border: 1px solid rgba(45,106,79,0.12);
+  padding: 14px;
+}
+.note strong{font-weight:950}
+.toast{
+  display:none;
+  margin-top:12px;
+  border-radius: 16px;
+  background: rgba(45,106,79,0.10);
+  border: 1px solid rgba(45,106,79,0.14);
+  padding: 10px 12px;
+  font-weight:850;
+}
+.toast.show{display:block}
+
+/* Footer */
+footer{padding: 26px 0 34px}
+.footer-shell{
+  border-radius: var(--radius-lg);
+  background: rgba(255,255,255,0.62);
+  border: 1px solid rgba(45,106,79,0.12);
+  box-shadow: var(--shadow-soft);
+  padding: 18px;
+}
+.footer-grid{display:grid;grid-template-columns: 1.6fr 1fr 1fr 1fr;gap: 14px}
+.footer-title{font-family:"Nunito", ui-sans-serif, system-ui;font-weight:950;letter-spacing:-0.02em;margin:0 0 6px}
+.footer-col a{display:block;padding:6px 0;color:rgba(31,42,36,0.78)}
+.footer-col a:hover{color:rgba(45,106,79,0.95)}
+.footer-bottom{margin-top:14px;border-top:1px solid rgba(45,106,79,0.12);padding-top:12px;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}
+.fineprint{color:rgba(31,42,36,0.70);font-size:13px}
+
+/* Utilities */
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr;}
+  h1{font-size: 40px}
+  .highlights-grid{grid-template-columns: repeat(2, 1fr)}
+  .two-col{grid-template-columns: 1fr}
+  .category-grid{grid-template-columns: repeat(2, 1fr)}
+  .newsletter{grid-template-columns: 1fr}
+  .footer-grid{grid-template-columns: 1fr 1fr}
+  .store{grid-template-columns: 1fr}
+}
+
+@media (max-width: 520px){
+  h1{font-size: 34px}
+  .nav{display:none}
+  .header-cta .btn-secondary{display:none}
+  .category-grid{grid-template-columns: 1fr}
+  .product-card{min-width: 220px;max-width:220px}
+}
+
*** End Patch
